  void BuildStudioCasino(){var casino=game.GetComponent<CafeCasino>();if(!casino)casino=game.gameObject.AddComponent<CafeCasino>();StudioChrome("NOIR / ÜST KAT","Royal Jackpot","Blackjack · 52 kart · As 1 veya 11 · Krupiye 17'de durur · Doğal 21, 3:2 öder");SText("KRUPİYE",268,220,800,25,15,studioGold);CardHand(casino.dealer,268,258,casino.Active);SText("SEN  /  "+(casino.player.Count>0?CafeCasino.Score(casino.player).ToString():"—"),268,395,800,25,15,studioGold);CardHand(casino.player,268,433,false);SText(casino.Result,268,566,970,35,22,ink);studioMessage.text="1 / 2 / 3: Bahis seç   ·   H: Kart çek   ·   S: Dur\nOyun içi coin · Bahis "+game.blackjackBet;if(casino.Active){SButton("KART ÇEK",268,610,300,44,()=>game.BlackjackHit(),true);SButton("DUR",590,610,300,44,()=>game.BlackjackStand());SButton("ELİ BİTİR & KALK",990,654,260,44,()=>{game.BlackjackStand();game.Continue();});}else{int[] bets={10,50,200};for(int i=0;i<3;i++){int bet=bets[i];SButton(bet+" COIN · OYNA",268+i*322,610,300,44,()=>game.StartBlackjack(bet),i==0);}}SBox(28,112,210,490,studioCard);SText("21\n\nİYİ BİR EL.\nSOĞUKKANLI\nBİR KARAR.\n\nAslar otomatik\n1 veya 11 sayılır.",48,140,170,350,22,studioGold);}
  void CardHand(List<int> cards,float x,float y,bool hidden){if(cards.Count==0){SText("Yeni el için bahis seç.",x,y,800,70,22,studioMuted);return;}for(int i=0;i<cards.Count;i++){bool back=hidden&&i>0;SBox(x+i*Mathf.Min(91,970f/Mathf.Max(1,cards.Count)),y,78,105,back?new Color(.3f,.18f,.23f):new Color(.92f,.89f,.82f));SText(back?"?":CafeCasino.Label(cards[i]),x+8+i*Mathf.Min(91,970f/Mathf.Max(1,cards.Count)),y+8,62,89,27,back?studioGold:cards[i]/13==1||cards[i]/13==2?new Color(.7f,.15f,.2f):studioBg,TextAnchor.MiddleCenter);}}
  void BuildStudioArcade(){var a=game.GetComponent<CafeStreetActivities>();StudioChrome("CADDE / BASKET NOKTASI","Son saniye şutu.","5 atış · Yeşil alanı yakala · Günde bir kez 3 isabete +20 coin ve +2 itibar");SCard("TUR",a.shots+" / 5","Tamamlanan atış",268,238,300);SCard("İSABET",a.hits.ToString(),"Bu tur",590,238,300);SCard("KİŞİSEL REKOR",game.data.hundred.basketBest+" / 5","Kaydında saklanır",912,238,338);SBox(268,402,982,76,studioCard);SBox(268+982*.39f,402,982*.22f,76,new Color(.15f,.4f,.3f));aimMarker=SBox(268,397,8,86,studioGold);SText(a.message,268,505,982,60,25,ink);SButton(a.playing?"ATIŞ YAP":"YENİ TUR",268,586,600,54,()=>{if(a.playing)a.Shoot();else a.Begin();},true);SText("BASKET\n\nKÜÇÜK BİR\nMOLA.\n\nYarıştığın kişi\nkendinsin.",40,145,185,390,24,studioGold);}
  void UpdateStudio(){FitStudioFrame();if(menu&&menu.gameObject.activeSelf&&studioPage=="arcade"&&aimMarker){var a=game.GetComponent<CafeStreetActivities>();aimMarker.anchoredPosition=new Vector2(268+974*a.Aim,-440);}}
 }
